mapper.select:
SELECT ( SELECT COUNT(*) FROM branch_stock bs WHERE bs.current_qty > 0 AND bs.expire_date IS NOT NULL AND DATEDIFF(bs.expire_date, CURDATE()) BETWEEN 0 AND 1
AND bs.branch_code = #{branchCode}
) AS urgentCount,
( SELECT COUNT(*) FROM branch_stock bs WHERE bs.current_qty > 0 AND bs.expire_date IS NOT NULL AND DATEDIFF(bs.expire_date, CURDATE()) BETWEEN 2 AND 3
AND bs.branch_code = #{branchCode}
) AS warningCount,
( SELECT COUNT(*) FROM branch_stock_disposal_history d
JOIN branch_stock_change_history bsch ON d.change_id = bsch.change_id
JOIN branch_stock bs ON bsch.branch_stock_code = bs.branch_stock_code
WHERE bsch.change_type = 'DISPOSAL'
AND bs.branch_code = #{branchCode}
AND DATE(bsch.changed_at) >= #{startDate}
AND DATE(bsch.changed_at) <= #{endDate}
) AS disposalCount
